  void ApplyTheme(){
   var p=ThemePalette.Get(Preferences);bool light=p.Light;string a=p.Start,b=p.End;
   double opacity=Preferences.Material=="Düz"||SystemParameters.HighContrast?1:Preferences.Tint;
   Resources["Surface"]=SurfaceBrush(a,b,opacity);Resources["Header"]=AllowsTransparency?Brushes.Transparent:SurfaceBrush(a,b,Preferences.Material=="Düz"?1:Math.Max(.85,opacity));
   string text=light?"#282C31":"#EFF2F5",muted=light?"#535C65":"#C0C8D2";
   string tile=ThemePalette.Mix(a,light?"#101820":"#D4DFEB",light?.06:.10),selectedColor=ThemePalette.Mix(a,light?"#101820":"#D4DFEB",light?.15:.22);
   if(ThemePalette.Contrast(muted,a)<4.5||ThemePalette.Contrast(muted,b)<4.5||ThemePalette.Contrast(muted,tile)<4.5)muted=text;
   Resources["Text"]=Brush(text);Resources["Muted"]=Brush(muted);Resources["Tile"]=Brush(tile);Resources["Hover"]=Brush(ThemePalette.Mix(a,light?"#101820":"#D4DFEB",light?.12:.26));Resources["Track"]=Brush(ThemePalette.Mix(a,light?"#101820":"#D4DFEB",.32));Resources["Selected"]=Brush(selectedColor);Resources["Accent"]=Brush(p.Accent);Resources["Popup"]=Brush(ThemePalette.Mix(a,b,.6));Resources["Nav"]=Brush(ThemePalette.Mix(a,light?"#101820":"#000000",.12));Resources["Clear"]=Brushes.Transparent;Resources["Edge"]=Brushes.Transparent;Resources["Action"]=Brush(light?"#343E38":"#DDE2E7");Resources["OnAction"]=Brush(light?"#F0F2EF":"#252D35");Resources["Cover"]=SurfaceBrush("#C6CACD","#E0E2E3",1);Resources["CoverIcon"]=Brush("#697178");
   if(SystemParameters.HighContrast){Resources["Surface"]=SystemColors.WindowBrush;Resources["Header"]=SystemColors.WindowBrush;Resources["Text"]=SystemColors.WindowTextBrush;Resources["Muted"]=SystemColors.WindowTextBrush;Resources["Accent"]=SystemColors.HighlightBrush;Resources["Tile"]=SystemColors.ControlBrush;Resources["Nav"]=SystemColors.WindowBrush;Resources["Selected"]=SystemColors.ControlDarkBrush;Resources["Popup"]=SystemColors.WindowBrush;Resources["Action"]=SystemColors.HighlightBrush;Resources["OnAction"]=SystemColors.HighlightTextBrush;}
  }
  Brush SurfaceBrush(string start,string end,double alpha){var a=(Color)ColorConverter.ConvertFromString(start);var b=(Color)ColorConverter.ConvertFromString(Preferences.Gradient?end:start);a.A=b.A=(byte)Math.Round(alpha*255);var brush=new LinearGradientBrush(a,b,new Point(0,0),new Point(1,1)){ColorInterpolationMode=ColorInterpolationMode.ScRgbLinearInterpolation};brush.Freeze();return brush;}
  static Brush Brush(string color){var b=new SolidColorBrush((Color)ColorConverter.ConvertFromString(color));b.Freeze();return b;}
  void ApplyMaterial(){if(new WindowInteropHelper(this).Handle==IntPtr.Zero)return;bool effect=Preferences.Material!="Düz"&&!SystemParameters.HighContrast;bool ok=Native.Backdrop(this,effect?Preferences.Material:"Düz",ThemePalette.Get(Preferences).Light);Native.RemoveFrame(this);if(effect&&!ok){var palette=ThemePalette.Get(Preferences);var fallback=SurfaceBrush(palette.Start,palette.End,1);Resources["Surface"]=fallback;Resources["Header"]=fallback;SetStatus("Bu yüzey desteklenmiyor; düz görünüm kullanılıyor.");}else if(status.StartsWith("Bu yüzey"))SetStatus("");}
