   bool testing=args.Contains("--tools-test")||args.Contains("--spotify-check")||args.Contains("--recovery-test")||args.Contains("--media-check")||args.Contains("--self-test")||args.Contains("--motion-test")||args.Contains("--benchmark");using(var singleton=new Mutex(false,"Local\\AdaDesktop-Window-v1")){
    if(!testing&&!singleton.WaitOne(0))return;
    try{var app=new Application{ShutdownMode=ShutdownMode.OnMainWindowClose};app.DispatcherUnhandledException+=delegate(object s,DispatcherUnhandledExceptionEventArgs e){Directory.CreateDirectory(Settings.DirectoryPath);File.AppendAllText(Path.Combine(Settings.DirectoryPath,"error.log"),DateTime.Now+" "+e.Exception+Environment.NewLine);if(testing){Directory.CreateDirectory(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"qa"));File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"qa","FAILED.txt"),e.Exception.ToString());e.Handled=true;app.Shutdown(1);return;}MessageBox.Show(e.Exception.Message,"Veilix");e.Handled=true;};var initial=testing?new Settings():Settings.Load();if(args.Contains("--transparent"))initial.Material="Şeffaf";var window=new AdaWindow(testing,args.Contains("--inspect"),initial);if(testing)window.Loaded+=async delegate{try{if(args.Contains("--tools-test"))await window.UtilityCheck();else if(args.Contains("--recovery-test")){var results=new List<string>();await window.CheckMediaRecovery(results);Directory.CreateDirectory(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"qa"));File.WriteAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"qa","recovery-report.txt"),results);window.Close();}else if(args.Contains("--media-check")||args.Contains("--spotify-check"))await window.MediaCheck(args.Contains("--spotify-check"));else if(args.Contains("--benchmark"))await window.Benchmark();else if(args.Contains("--motion-test"))await window.MotionTest();else await window.SelfTest();}catch(Exception ex){Directory.CreateDirectory(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"qa"));File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"qa","FAILED.txt"),ex.ToString());Environment.ExitCode=1;window.Close();}};app.Run(window);}catch(Exception ex){Directory.CreateDirectory(Settings.DirectoryPath);File.WriteAllText(Path.Combine(Settings.DirectoryPath,"fatal.log"),ex.ToString());MessageBox.Show(ex.Message,"Veilix başlatılamadı");}finally{if(!testing)singleton.ReleaseMutex();}
   }
  }
 }
